<?php defined('ABSPATH') || exit;$editing=$persona!==null;$kind=$editing?$persona->kind():'person';$currentFaction=$editing?$persona->factionId():''; ?>
<form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="gmrc-personae-form__body"><input type="hidden" name="action" value="gmrc_app_request"><input type="hidden" name="gmrc_route" value="<?php echo esc_attr($route); ?>"><input type="hidden" name="_method" value="<?php echo $editing?'PUT':'POST'; ?>"><input type="hidden" name="gmrc_nonce" value="<?php echo esc_attr(wp_create_nonce('gmrc_dm_personae_'.$campaign->id())); ?>">
<div class="gmrc-personae-form__row"><label>Record type<select name="record_kind"><option value="person" <?php selected($kind,'person'); ?>>Person / NPC</option><option value="faction" <?php selected($kind,'faction'); ?>>Faction</option></select></label><label>Visibility<select name="visibility"><option value="keeper" <?php selected($editing?$persona->visibility():'keeper','keeper'); ?>>Keeper only</option><option value="players" <?php selected($editing?$persona->visibility():'keeper','players'); ?>>Player-visible</option></select></label><label>Faction / allegiance<select name="faction_id"><option value="">No faction</option><?php foreach(($factions??[]) as $faction): if($editing&&$faction->id()===$persona->id()){continue;} ?><option value="<?php echo esc_attr($faction->id()); ?>" <?php selected($currentFaction,$faction->id()); ?>><?php echo esc_html($faction->name()); ?></option><?php endforeach; ?></select></label></div>
<label>Name<input type="text" name="name" maxlength="140" required value="<?php echo esc_attr($editing?$persona->name():''); ?>"></label><label>Role / title<input type="text" name="role" maxlength="180" value="<?php echo esc_attr($editing?$persona->role():''); ?>" placeholder="Innkeeper, rival cartographer, merchant guild, secret society…"></label><label>At-a-glance description<textarea name="summary" rows="4" maxlength="600" placeholder="What should the Keeper remember immediately about this person or faction?"><?php echo esc_textarea($editing?$persona->summary():''); ?></textarea></label><label>Private Keeper notes<textarea name="keeper_notes" rows="12" maxlength="20000" placeholder="Motives, secrets, voice, relationships, leverage, plans, suspicions…"><?php echo esc_textarea($editing?$persona->notes():''); ?></textarea></label><p class="gmrc-personae-form__hint"><strong>Board seam:</strong> this is the canonical campaign identity. The future Conspiracy Board will pin this record rather than copy it.</p><button class="gmrc-personae-button" type="submit"><?php echo $editing?'Update Dramatis Personae':'Enter Record'; ?></button></form>
